Here's an example of how to implement this:

```javascript
function debounceAsync(fn, delay) {
    let timeoutId;
    let abortController;

    return function (...args) {
        // If there's an existing timeout, clear it
        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        // If there's an ongoing request, abort it
        if (abortController) {
            abortController.abort();
        }

        // Create a new AbortController for the new request
        abortController = new AbortController();
        const signal = abortController.signal;

        // Set a new timeout
        timeoutId = setTimeout(async () => {
            try {
                // Call the async function with the provided arguments and signal
                const result = await fn(...args, { signal });
                console.log('API call result:', result);
            } catch (error) {
                if (error.name === 'AbortError') {
                    console.log('API call aborted:', error.message);
                } else {
                    console.error('API call error:', error);
                }
            } finally {
                // Clear the timeout and abort controller after execution
                timeoutId = null;
                abortController = null;
            }
        }, delay);
    };
}

// Example usage
async function fetchData(query, { signal }) {
    const response = await fetch(`https://api.example.com/data?query=${query}`, { signal });
    if (!response.ok) {
        throw new Error('Network response was not ok');
    }
    return response.json();
}

// Create a debounced version of the fetchData function
const debouncedFetchData = debounceAsync(fetchData, 300);

// Example of calling the debounced function
document.getElementById('inputField').addEventListener('input', (event) => {
    debouncedFetchData(event.target.value);
});
```

