    // Always include at least one character from each set
    $password .= $lowercase[random_int(0, strlen($lowercase) - 1)];
    $password .= $uppercase[random_int(0, strlen($uppercase) - 1)];
    $password .= $numbers[random_int(0, strlen($numbers) - 1)];

    // Include special characters if required
    if ($includeSpecialChars) {
        $password .= $specialChars[random_int(0, strlen($specialChars) - 1)];
    }

    // Calculate how many more characters to add
    $remainingLength = $length - strlen($password);
    $allChars = $lowercase . $uppercase . $numbers;

    if ($includeSpecialChars) {
        $allChars .= $specialChars;
    }

    // Fill the rest of the password length with random characters
    for ($i = 0; $i < $remainingLength; $i++) {
        $password .= $allChars[random_int(0, strlen($allChars) - 1)];
    }

    // Shuffle the password to ensure randomness
    return str_shuffle($password);
}

