### Debounce Function Implementation

```javascript
function debounceAsync(fn, delay) {
    let timeoutId = null;
    let abortController = null;

    return function (...args) {
        // Clear the existing timeout, if any
        if (timeoutId) {
            clearTimeout(timeoutId);
            if (abortController) {
                abortController.abort(); // Abort ongoing fetch request
            }
        }

        // Create a new AbortController for the new fetch request
        abortController = new AbortController();
        const signal = abortController.signal;

        // Set a new timeout to call the function after the specified delay
        timeoutId = setTimeout(async () => {
            try {
                const result = await fn(...args, { signal }); // Call the async function
                console.log('Fetch result:', result); // Handle success
            } catch (error) {
                if (error.name === 'AbortError') {
                    console.log('Request was aborted'); // Handle aborted request
                } else {
                    console.error('Fetch error:', error); // Handle other errors
                }
            } finally {
                timeoutId = null; // Cleanup timeout
                abortController = null; // Cleanup abort controller
            }
        }, delay);
    };
}
```

